INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('a75f92ae-d37c-5796-b721-065c54a568f5','45cedaff-95aa-5add-89b9-af8480a7f5df','Plurals: -es endings',0,'LESSON',70,$j$[{"type": "rule", "text": "We add -es to make the plural of nouns that end in -s, -ss, -x, -sh or -ch."}, {"type": "examples", "items": ["fox - foxes", "bus - buses", "dress - dresses", "watch - watches"]}]$j$::jsonb);
