INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('e27e9420-6e47-5924-a292-7e7c6fccb9a1','a0000000-0000-4000-8000-0000000000f3','Блок 18. Prepositions of Place',18,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('ec10816a-70e5-5148-b096-e132943adcf0','e27e9420-6e47-5924-a292-7e7c6fccb9a1','Prepositions of Place',0,'LESSON',70,$j$[{"type": "rule", "text": "We use prepositions to say where things are: in, on, under, behind and next to."}, {"type": "examples", "items": ["The computer is on the desk.", "The cat is in the basket.", "The ball is under the bed."]}]$j$::jsonb);
