INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('ee859292-73b8-5414-8e0d-3db840a044a8','a0000000-0000-4000-8000-0000000000f3','Блок 19. Have Got',19,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('5747ea9c-eb39-5a92-a43e-39cc07d89a79','ee859292-73b8-5414-8e0d-3db840a044a8','Have Got',0,'LESSON',70,$j$[{"type": "rule", "text": "We use have got / has got to talk about what we own and how we look. Use has got with he, she, it and have got with I, you, we, they. Remember: 've = have."}, {"type": "examples", "items": ["I've got a teddy bear.", "She's got blue eyes and fair hair.", "Has he got a bike? Yes, he has. / No, he hasn't."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('fb6a0dad-66a9-5638-bf0c-56b9b3299591','5747ea9c-eb39-5a92-a43e-39cc07d89a79',0,'CHOOSE','Выбери правильную форму: has got или have got.',$j${"items": [{"before": "She", "after": "blue eyes.", "options": [{"id": "o1", "label": "has got"}, {"id": "o2", "label": "have got"}]}, {"before": "They", "after": "a big house.", "options": [{"id": "o1", "label": "has got"}, {"id": "o2", "label": "have got"}]}, {"before": "Jim", "after": "fair hair.", "options": [{"id": "o1", "label": "has got"}, {"id": "o2", "label": "have got"}]}]}$j$::jsonb,10);
