INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('3a9b1e45-c566-5999-8916-846e4ee3780e','a0000000-0000-4000-8000-0000000000f3','Блок 20. Can - Abilities',20,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('0d08d196-709b-58ec-9e68-7f73389687f4','3a9b1e45-c566-5999-8916-846e4ee3780e','Can - Abilities',0,'LESSON',70,$j$[{"type": "rule", "text": "We use can to talk about ability. Short answers: Yes, I/you/he/she/it can. No, I/you/he/she/it can't. Can we/you/they swim? Yes, we/you/they can. No, we/you/they can't."}, {"type": "examples", "items": ["Can you swim? Yes, I can.", "Can he ride a bike? No, he can't."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('a89dcc92-6266-5706-8fd2-c5e6a5f9780c','0d08d196-709b-58ec-9e68-7f73389687f4',0,'CHOOSE','Выбери правильный вариант: can или can''t.',$j${"items": [{"before": "A fish", "after": "swim.", "options": [{"id": "o1", "label": "can"}, {"id": "o2", "label": "can't"}]}, {"before": "A cat", "after": "fly.", "options": [{"id": "o1", "label": "can"}, {"id": "o2", "label": "can't"}]}]}$j$::jsonb,10);
