INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('15f779a2-4aaa-5833-bcf6-b79e23f87ec1','a0000000-0000-4000-8000-0000000000f3','Блок 22. Present Simple and some/any',22,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('7b07def7-1a6b-5481-81ea-fc8a5e3a8ce4','15f779a2-4aaa-5833-bcf6-b79e23f87ec1','Present Simple and some/any',0,'LESSON',70,$j$[{"type": "rule", "text": "Present Simple (like): Affirmative: I like carrots. Negative: I don't like carrots. Interrogative: Do you like tomatoes? Yes, I do. / No, I don't."}, {"type": "rule", "text": "We use some in affirmative sentences only, with countable nouns in the plural and with uncountable nouns. e.g. There are some eggs. There is some cheese."}, {"type": "rule", "text": "We use any in negative and interrogative sentences only, with countable nouns in the plural and with uncountable nouns. e.g. Are there any tomatoes? There aren't any apples. There isn't any milk."}, {"type": "examples", "items": ["There are some sausages.", "There isn't any cheese.", "Do they like fish? No, they don't."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('2ad2a254-b24e-5cda-99cd-47656204927c','7b07def7-1a6b-5481-81ea-fc8a5e3a8ce4',0,'FILL_BLANK','Прочитай и вставь some или any.',$j${"items": [{"before": "1 Mum, is there", "after": "apple juice?"}, {"before": "2 We've got", "after": "orange juice,"}, {"before": "but we haven't got", "after": "milk."}, {"before": "3 Sorry, but there isn't", "after": "sugar!"}, {"before": "4 Is there", "after": "spaghetti in the cupboard?"}, {"before": "5 There isn't", "after": "rice on the table."}, {"before": "6 There aren't", "after": "sandwiches in my lunch box."}, {"before": "7 There is", "after": "ice cream in the fridge."}, {"before": "8 Are there", "after": "tomatoes in the garden?"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('2ad2a254-b24e-5cda-99cd-47656204927c',$j${"items": [{"accept": ["any"]}, {"accept": ["some"]}, {"accept": ["any"]}, {"accept": ["any"]}, {"accept": ["any"]}, {"accept": ["any"]}, {"accept": ["any"]}, {"accept": ["some"]}, {"accept": ["any"]}]}$j$::jsonb,'');
